  "资金与投资资产分散，难以统一掌握？": "Finding it hard to track scattered cash and investments?",
  "连接企业账户、现金、投资和持仓信息，形成企业自身的资金与投资资产视图。": "Connect corporate accounts, cash, investments and holdings to create a unified view of your company's funds and investment assets.",
  "有闲置资金，但哪些钱适合投资？": "Have idle cash, but unsure how much you can invest?",
  "从经营资金与流动性安排出发，更清晰地区分日常经营、流动性储备和阶段性可投资资金。": "Start with operating needs and liquidity planning to distinguish daily operating cash, liquidity reserves and temporarily investable funds.",
  "理财产品分散，选择与交易成本高？": "Too many scattered products and costly selection and trading?",
