  "连接现金管理、基金、债券、结构性产品及其他适用财富产品，并结合币种、期限、流动性、风险和申赎规则配置产品范围。": "Connect cash management, funds, bonds, structured products and other suitable wealth products, with product availability configured by currency, tenor, liquidity, risk and subscription / redemption rules.",
