  "特定期限配置": "Fixed-Tenor Allocations",
  "投资交易": "Investment Trading",
  "在统一入口完成理财投资操作": "Complete Investment Operations in One Place",
  "企业可在统一业务入口查看产品与详情，完成申购、订单跟踪、交易记录查询和赎回；部分产品可根据实际业务涉及询价或报价。": "Companies can view products and details, subscribe, track orders, review trades and redeem through one entry point. Some products may involve requests for quotes or quotations, depending on the business.",
