  "资产与流动性": "Assets and Liquidity",
  "持续掌握资产和未来资金安排": "Stay on Top of Assets and Future Cash Needs",
  "将总资产、持仓、资金流水、到期、赎回、派息与结单放在连续的资产管理视角中，帮助企业关注投资资产何时重新成为可用资金。": "Bring total assets, holdings, cash movements, maturities, redemptions, distributions and statements into a continuous asset management view, helping companies track when investments become available cash again.",
