  "多资产财富产品": "Multi-Asset Wealth Products",
  "根据企业实际需求与准入条件，连接现金管理、基金、债券、结构性产品及其他适用资产。": "Connect cash management, funds, bonds, structured products and other suitable assets according to corporate needs and eligibility.",
