  "把分散的 RWA 环节，连接成一套完整体系": "Connect Fragmented RWA Processes in One Framework",
  "RWA 并不只是一次 Token 发行。FinRWA 将资产设计、技术、链上管理、金融运营、合规和分销等关键能力连接到统一体系中。": "RWA extends beyond token issuance. FinRWA connects asset design, technology, on-chain management, financial operations, compliance and distribution.",
