  "建立在财富专业知识之上的金融智能": "Financial Intelligence Built on Wealth Expertise",
  "Finloop AI 将财富管理经验、金融数据与业务工作流连接起来，让 AI 不止理解问题，更能在真实业务环境中完成分析、协作与后续执行。": "Finloop AI connects wealth management experience, financial data and business workflows, enabling analysis, collaboration and follow-through in real business environments.",
  "财富专业智能": "Wealth Expertise",
