  "工作流智能": "Workflow Intelligence",
  "将 AI 能力嵌入研究、分析、审批与运营流程，实现任务自动化、协同处理与人机配合。": "Embed AI in research, analysis, approval and operational processes for task automation, collaboration and human–AI cooperation.",
  "Finloop 金融智能中枢": "Finloop Financial Intelligence Hub",
  "连接数据、模型、知识与工作流，让专业能力持续进入业务流程。": "Connect data, models, knowledge and workflows to bring expertise into business processes.",
  "让 AI 贯穿财富管理全生命周期": "AI Across the Wealth Management Lifecycle",
  "从发现需求、理解客户和评估产品，到方案匹配、客户触达与持续运营，Finloop AI 将专业能力嵌入每个关键环节，让信息处理更高效、判断依据更清晰、后续行动更连贯。": "From identifying needs and understanding clients to evaluating products, matching solutions, engaging clients and ongoing operations, Finloop AI embeds professional capabilities at every key stage for efficient information processing, clearer decisions and connected actions.",
