  "覆盖数字资产全链路解决方案": "End-to-End Digital Asset Solutions",
  "从现实资产代币化，到虚拟资产与稳定币产品接入，再到合作机构产品分销，按业务目标灵活组合产品、交易、运营与链上能力。": "From real asset tokenization to virtual asset and stablecoin product access and partner product distribution, combine products, trading, operations and on-chain capabilities around business objectives.",
  "从模型治理和企业数据，到 Agent、工作流与持续运营，形成可落地的企业 AI 能力。": "Build practical enterprise AI capabilities, from model governance and enterprise data to Agents, workflows and ongoing operations.",
  "解决方案核心能力": "Core Solution Capabilities",
  "FRP · FinOne · FinMix · 链上基础能力": "FRP · FinOne · FinMix · On-Chain Foundations",
  "FinWork · 星路通 · AI PaaS · 星智通 MaaS": "FinWork · Fintelligence · AI PaaS · FinAMH MaaS",
  "相关产品与平台": "Related Products and Platforms",
  "进入对应产品，了解资产代币化与财富业务核心能力。": "Explore products to understand asset tokenization and core wealth capabilities.",
  "提供现实资产上链、资产代币化与数字化发行技术服务。": "Technology services for real asset tokenization and digital issuance.",
  "支撑产品、用户、账户、订单、渠道配置与财富业务运营管理。": "Support products, users, accounts, orders, channel configuration and wealth operations.",
  "了解产品 →": "Explore Product →",
  "覆盖发行、产品接入与分销全链路": "From Issuance and Product Access to Distribution",
  "交付物与合作方式": "Deliverables and Engagement Options",
  "根据你是现实资产方、数字资产产品需求方或产品提供方，组合相应业务能力。": "Combine capabilities according to your role as an asset owner, digital asset product buyer or product provider.",
  "从场景诊断开始，逐步进入首批场景共建和企业级平台运营。": "Start with use case assessment, then build initial scenarios and progress to enterprise platform operations.",
  "了解更多 →": "Learn More →",
  "FDE 不是另一层软件，而是一种深入客户业务现场的工程交付方式，以业务目标倒推技术实现。": "FDE is an engineering delivery approach embedded in client businesses, designing technology around business objectives rather than adding another software layer.",
  "与业务角色共同梳理高频任务、隐性规则、决策节点与真正值得改变的流程。": "Work with business teams to identify frequent tasks, implicit rules, decision points and processes worth changing.",
  "连接投管、ERP、OA、知识库、数据库与权限体系，让 AI 获得执行真实任务所需的上下文和工具。": "Connect investment management, ERP, OA, knowledge bases, databases and permissions to give AI the context and tools for real tasks.",
  "通过原型验证、系统集成、治理上线与持续运营，把模型、Skills 和 Agent 变成可控的业务动作。": "Turn models, Skills and Agents into controlled business actions through prototypes, integration, governed launch and ongoing operations.",
  "FDE 团队": "FDE Team",
  "可复用 AI 技术底座": "Reusable AI Infrastructure",
  "进入生产的企业 AI": "Enterprise AI in Production",
  "FDE-AI 落地方法": "FDE-AI Implementation Method",
  "由业务场景诊断进入设计、构建、部署和持续运营。": "Progress from business use case assessment through design, development, deployment and ongoing operations.",
  "从角色和项目评估，到方案设计、系统连接、上线与持续运营。": "From role and project assessment to solution design, system integration, launch and ongoing operations.",
  "仅展示已确认的信息；客户名称、项目结果与合作性质需完成授权后公开。": "Only confirmed information is shown. Client names, project results and partnership details require authorization before publication.",
  "企业 AI 进入专业业务流程场景": "Enterprise AI in Professional Business Workflows",
  "无论是现实资产代币化、接入虚拟资产与稳定币产品，还是将已有数字资产产品接入星路平台分销，都可以根据业务目标构建相应方案。": "Build solutions around your objectives, whether tokenizing real assets, accessing virtual asset and stablecoin products, or distributing existing digital asset products through Finloop.",
  "从真实业务、高价值任务与现有系统出发，规划首个可落地的 AI 场景。": "Plan the first practical AI use case around real business needs, high-value tasks and existing systems.",
  "客户、账户与资产分散，难以统一管理？": "Struggling to manage scattered clients, accounts and assets?",
  "统一连接客户资料、账户、风险属性、资产与投资信息，形成更完整的客户财富视图。": "Connect client information, accounts, risk profiles, assets and investments for a fuller client wealth view.",
  "投资管理与交易割裂，协作成本高？": "High collaboration costs from disconnected investment management and trading?",
  "贯通产品选择、投资建议、订单、执行与运营流程，让不同角色共享业务状态。": "Connect product selection, investment proposals, orders, execution and operations so different roles share business status.",
  "多资产产品接入复杂，持续维护成本高？": "Complex multi-asset integration and high ongoing maintenance costs?",
  "通过统一产品与交易能力，按需接入基金、债券、结构性产品等不同金融品类。": "Connect funds, bonds, structured products and other asset classes as needed through unified product and trading capabilities.",
  "业务持续扩展，现有系统难以支撑？": "Is business growth outpacing your existing systems?",
  "保留机构已有业务基础，通过灵活配置与系统连接补充所需能力，支持后续扩展。": "Preserve existing business foundations, adding capabilities through flexible configuration and system connectivity to support future growth.",
  "建立统一的客户与账户基础": "Build Unified Client and Account Foundations",
  "连接客户资料、身份审查、风险属性、账户、资产与持仓信息，形成完整的客户财富视图，并为后续投资管理与持续服务提供统一基础。": "Connect client information, identity checks, risk profiles, accounts, assets and holdings into a complete client wealth view and a common foundation for investment management and ongoing services.",
  "数字开户": "Digital Onboarding",
