  "将客户资产、投资目标、资产配置与投资组合连接起来，支持组合跟踪、持续监控和投资记录管理，帮助机构建立连贯的投资管理流程。": "Connect client assets, investment objectives, allocation and portfolios, supporting portfolio tracking, ongoing monitoring and investment records for continuous investment management.",
