  "全品类产品": "Multi-Asset Products",
  "按需连接全品类财富产品": "Connect Wealth Products Across Asset Classes",
  "通过统一财富产品体系连接现金管理、基金、债券、结构性产品及其他适用产品，机构可根据目标客户与发展阶段灵活选择产品范围。": "Connect cash management, funds, bonds, structured products and other suitable products through one wealth framework, choosing product scope according to target clients and business stage.",
