  "让财富服务延伸至交易之后": "Extend Wealth Services Beyond the Trade",
  "将持仓、资金、清结算、产品生命周期、结单与报告持续纳入财富业务运营体系，使交易后的资产服务与业务状态保持连贯。": "Connect holdings, cash, clearing, settlement, product lifecycles, statements and reports in wealth operations to maintain continuity in post-trade services and business status.",
