  "让系统容量随业务规模一起增长": "Scale System Capacity with the Business",
  "采用单元化与分布式设计，帮助系统应对业务规模增长、高可用和故障隔离要求。": "Cell-based and distributed design supports business growth, high availability and fault isolation.",
