  "技术平台 | Finloop 星路科技": "Technology Platform | Finloop",
  "了解 Finloop 以产品、账户与交易为核心构建的财富管理技术基础设施。": "Explore Finloop's wealth management infrastructure built around products, accounts and trading.",
