  "白标和嵌入有什么区别？": "How do white-label and embedded services differ?",
  "白标以独立 App 承接完整终端，通常由合作机构运营；嵌入式 H5 进入已有 App 的用户旅程，通常由星路运营。": "White-label services provide a complete standalone app, usually operated by the partner. Embedded H5 joins an existing app's user journey and is usually operated by Finloop.",
  "我们已有柜台，还可以继续使用吗？": "Can we keep using our existing dealing system?",
  "白标 App 可按实际架构连接客户现有柜台，或使用星路自研 FinMix。": "The white-label app can connect to existing client dealing systems or Finloop's proprietary FinMix, depending on the architecture.",
  "白标客户是否拥有自己的管理后台？": "Do white-label clients have their own management back office?",
  "合作机构可通过 FinOne 管理产品、用户、账户、订单与运营配置。": "Partners can use FinOne to manage products, users, accounts, orders and operational settings.",
  "财富 H5 是否必须显示星路品牌？": "Must wealth H5 display Finloop branding?",
  "前端可保持合作机构品牌，但开户、协议、风险披露、交易等必要环节需按法律关系披露服务主体。": "The frontend can retain the partner brand, while onboarding, agreements, risk disclosures and trading must identify service entities according to the legal relationships.",
  "企业财富 Web 是星企通吗？": "Is Corporate Wealth Web the same as Finterprise?",
  "它不是企业版白标网站，而是在跨境支付平台企业场景中接入星企通业务能力和 FinOne 中台。": "It integrates Finterprise capabilities and the FinOne middle office into corporate cross-border payment experiences rather than providing a corporate white-label website.",
  "产品范围按交付模式、目标客群、柜台和准入条件分别确认。": "Product scope is confirmed by delivery model, target clients, dealing system and eligibility.",
  "是否支持港股 / 美股？": "Are Hong Kong and US stocks supported?",
  "港股与美股能力尚在开发中，不作为已上线能力表述。": "Hong Kong and US securities capabilities are still in development and are not presented as launched features.",
  "是否支持自定义 UI？": "Is custom UI supported?",
  "当前可确认 Logo、品牌名称与主色；其他组件级定制范围待确认，不承诺“完全自定义 UI”。": "Confirmed customization includes logos, brand names and primary colors. Other component-level customization is pending confirmation; fully custom UI is not promised.",
  "谁负责 App 上架？": "Who handles app store publication?",
  "App Store / Google Play 上架责任需在合作方案中确认。": "App Store / Google Play publication responsibilities must be agreed in the partnership plan.",
  "嵌入模式是否可以开放 FinOne 权限？": "Can embedded partners access FinOne?",
  "嵌入模式通常由星路运营；是否开放部分 FinOne 权限待确认。": "Embedded services are usually operated by Finloop. Access to selected FinOne permissions remains to be confirmed.",
  "白标与嵌入式金融解决方案": "White-Label and Embedded Finance Solutions",
  "财富服务，融入品牌与客户场景": "Wealth Services within Your Brand and Client Experiences",
  "通过白标 App、嵌入式财富 H5 和企业财富 Web，将多资产财富服务带入合作机构已有品牌、渠道与客户关系，并由统一财富中台持续支撑产品与运营。": "White-label apps, embedded wealth H5 and corporate wealth web bring multi-asset services to partner brands, channels and client relationships, with continuous product and operational support from a unified wealth middle office.",
  "已有品牌与客户，财富服务却难以快速上线": "An Established Brand and Clients, but Wealth Services Are Slow to Launch",
  "从零建设财富业务，往往需要同时面对系统建设、客户体验、既有架构连接与持续运营等多重挑战。": "Building wealth services from scratch involves systems, client experiences, existing architecture integration and ongoing operations.",
  "自建周期长、成本高": "Long Timelines and High Development Costs",
  "账户、产品、交易、持仓与运营能力涉及多个系统，从零搭建需要大量资源与时间。": "Accounts, products, trading, holdings and operations span multiple systems and require significant time and resources to build.",
  "客户体验容易割裂": "Fragmented Client Experiences",
  "开户、产品查看、交易与持仓分散在不同入口，容易中断原有品牌体验。": "Separate onboarding, product, trading and holdings entry points can interrupt the brand experience.",
  "新能力难融入现有架构": "New Capabilities Are Hard to Integrate",
  "新增财富服务需要与已有登录、客户、柜台及业务系统稳定连接。": "Wealth services need reliable connections to existing login, client, dealing and business systems.",
  "运营与合规边界复杂": "Complex Operational and Compliance Boundaries",
  "品牌展示、账户关系、运营责任与信息披露需要在上线前明确界定。": "Branding, account relationships, operational responsibilities and disclosures must be defined before launch.",
  "选择适合你的财富服务模式": "Choose the Right Wealth Service Model",
  "三种模式共享 FinOne 财富核心，但采购目标、运营责任、账户关系与品牌披露不同。": "Three models share the FinOne wealth core but differ in purchasing objectives, operational responsibilities, account relationships and brand disclosures.",
