  "星企通围绕企业现金管理需求，为企业提供多样化的投资路径，通过货币基金、固定票息票据、债券基金等方式，在兼顾流动性与风险水平的同时，帮助企业提升闲置资金的使用效率。": "Finterprise offers money market funds, fixed coupon notes, bond funds and other investment paths around corporate cash needs, helping improve idle cash efficiency while considering liquidity and risk.",
  "一站连接多类企业投资产品": "One Entry to Multiple Corporate Investment Products",
  "货币基金、存款及公募基金": "Money Market Funds, Deposits and Public Funds",
  "满足企业日常流动性管理与不同周期的资金安排。": "Support daily liquidity management and cash needs across investment horizons.",
  "多资产配置": "Multi-Asset Allocation",
