  "从开户到投资，企业资金管理一站完成": "Corporate Cash Management from Onboarding to Investing in One Place",
  "将企业账户、资金流转、投资交易与资产信息集中在一个平台，让资金管理从分散操作走向统一、透明与高效。": "Bring accounts, cash movements, trading and assets onto one platform for unified, transparent and efficient management.",
  "他们都在用星企通管理企业资金": "Managing Corporate Cash with Finterprise",
  "了解企业如何通过星企通连接资金状态、现金管理、投资交易与资产查询。": "See how companies connect cash positions, cash management, trading and asset queries through Finterprise.",
  "典型企业资金管理场景": "Typical Corporate Cash Management Scenario",
  "通过统一企业资金视图，连接阶段性闲置资金的管理、投资与后续查询。": "A unified corporate cash view connects temporarily idle cash management, investment and subsequent enquiries.",
