  "Finloop 星路科技总部位于香港，为金融机构、数字平台和企业提供财富产品连接、数字化平台、投资交易、RWA 与 AI 解决方案。品牌概念为 Web2 × Web3 × AI。": "Headquartered in Hong Kong, Finloop provides financial institutions, digital platforms and enterprises with wealth product connectivity, digital platforms, trading, RWA and AI solutions. Its brand concept is Web2 × Web3 × AI.",
  "涵盖现金管理、公募基金、私募基金、债券、结构性产品、保险、虚拟资产与 RWA。产品可售范围和适当性需按主体、地区及客户条件确认。": "Cash management, public funds, private funds, bonds, structured products, insurance, virtual assets and RWA. Availability and suitability depend on the entity, jurisdiction and client eligibility.",
  "连接 USD、HKD、CNH 等多币种货币基金，支持企业与金融机构现金配置、申赎和资产查看。": "Connect USD, HKD, CNH and other money market funds for corporate and institutional cash allocation, subscriptions, redemptions and asset views.",
  "连接全球基金产品，将产品、客户适当性、交易、持仓和运营连接在同一业务链路中。": "Connect global funds, product information, suitability, trading, holdings and operations in one process.",
  "面向专业投资者的私募产品货架与机构业务流程，具体可售范围按主体、地区及适当性要求确认。": "Private products and institutional processes for professional investors, subject to entity, jurisdiction and suitability requirements.",
  "固定收益产品信息、询价、订单与存续管理。": "Fixed-income information, quotations, orders and lifecycle management.",
  "覆盖 FCN、Sharkfin、Step-down SCN、BEN、ELN、DCN 等结构，连接多发行机构，覆盖零售与专业投资者场景，需确认适当性。": "FCN, Sharkfin, Step-down SCN, BEN, ELN and DCN structures across issuers for retail and professional investors, subject to suitability.",
  "保险纳入全品类财富产品货架。保险展业及保单管理能力不在本页产品范围内。": "Insurance is included in the multi-asset product shelf. Insurance distribution operations and policy management are outside this page's scope.",
  "虚拟资产产品": "Virtual Asset Products",
  "连接虚拟资产 ETF 等投资产品；KYT、钱包及出入金属于数字资产基础设施，不应混同为投资产品。": "Virtual asset ETFs and other investment products. KYT, wallets, deposits and withdrawals are infrastructure, not investment products.",
  "RWA 产品": "RWA Products",
  "代币化基金、证券相关 Token 与真实资产支持型 RWA 产品；资产上链、钱包与分销基础设施由 FinRWA 解决方案承接。": "Tokenized funds, securities-related tokens and real asset-backed RWA. FinRWA provides tokenization, wallet and distribution infrastructure.",
  "承载账户、产品、交易与资产的财富核心。": "The wealth core for accounts, products, trading and assets.",
  "面向 EAM 与家族办公室的财富管理 SaaS。": "Wealth management SaaS for EAMs and family offices.",
  "企业现金与财富管理平台，适用于企业资金管理需求。": "A corporate cash and wealth platform for corporate treasury needs.",
