  "真实资产上链与资产代币化服务。此链接为官网导航提供的外部产品站。": "Real asset tokenization services. This is an external product site linked from the official navigation.",
  "财富核心、交易基础设施与开放连接。开放接口覆盖鉴权、基金、债券与结构性产品，支持加密与 IP 白名单、企业统一身份认证及细粒度权限。": "Wealth core, trading infrastructure and open connectivity. Interfaces cover authentication, funds, bonds and structured products, with encryption, IP allowlists, enterprise identity and fine-grained permissions.",
