  "Finloop 以金融业务和产品能力为基础，连接业务应用、财富核心、交易基础设施、数字资产与 AI。": "Finloop 以金融業務和產品能力為基礎，連接業務應用、財富核心、交易基礎設施、數字資產與 AI。",
  "Finloop 依托复星财富控股旗下持牌金融机构体系开展相关财富和金融科技业务，并持续获得香港政府、金融科技及专业投资行业的关注与认可。": "Finloop 依託復星財富控股旗下持牌金融機構體系開展相關財富和金融科技業務，並持續獲得香港政府、金融科技及專業投資行業的關注與認可。",
  "Finloop 具备真实金融产品和业务基础，而不仅是软件能力。平台覆盖现金管理、公募基金、私募基金、债券、结构性产品、保险与数字资产/RWA。": "Finloop 具備真實金融產品和業務基礎，而不僅是軟件能力。平台覆蓋現金管理、公募基金、私募基金、債券、結構性產品、保險與數字資產/RWA。",
