  "Finloop 星路科技总部位于香港，为金融机构、数字平台和企业提供财富产品连接、数字化平台、投资交易、RWA 与 AI 解决方案。品牌概念为 Web2 × Web3 × AI。": "Finloop 星路科技總部位於香港，為金融機構、數字平台和企業提供財富產品連接、數字化平台、投資交易、RWA 與 AI 解決方案。品牌概念為 Web2 × Web3 × AI。",
  "Finloop 星路科技总部位于香港，是复星财富控股旗下的机构财富科技平台，连接传统财富、机构交易、数字资产与 AI。": "Finloop 星路科技總部位於香港，是復星財富控股旗下的機構財富科技平台，連接傳統財富、機構交易、數字資產與 AI。",
