  "RWA 基础设施": "RWA 基礎設施",
  "RWA 将传统金融产品与真实资产进一步连接至链上基础设施，使资产能够以新的数字化形式进行管理、流转和分销。": "RWA 將傳統金融產品與真實資產進一步連接至鏈上基礎設施，使資產能夠以新的數字化形式進行管理、流轉和分銷。",
  "RWA 并不只是一次 Token 发行。FinRWA 将资产设计、技术、链上管理、金融运营、合规和分销等关键能力连接到统一体系中。": "RWA 並不只是一次 Token 發行。FinRWA 將資產設計、技術、鏈上管理、金融運營、合規和分銷等關鍵能力連接到統一體系中。",
