  "RWA 项目通常涉及发行人、技术服务、托管、合规及分销等不同角色，资产上链只是完整流程中的一个环节。": "RWA 項目通常涉及發行人、技術服務、托管、合規及分銷等不同角色，資產上鏈只是完整流程中的一個環節。",
