  "从财富业务搭建到规模化运营，构建一体化数字财富平台": "從財富業務搭建到規模化運營，構建一體化數字財富平台",
  "从财富前端、产品展示到投资账户、交易及资产服务，快速补齐客户侧数字化能力。": "從財富前端、產品展示到投資賬戶、交易及資產服務，快速補齊客戶側數字化能力。",
  "从财富核心、机构工作台和企业资金管理，到数字资产、AI 与交易基础设施，进入对应平台了解产品定位与能力范围。": "從財富核心、機構工作台和企業資金管理，到數字資產、AI 與交易基礎設施，進入對應平台瞭解產品定位與能力範圍。",
  "从账户和金融产品，到交易、运营与 AI，FinOne 帮助机构在统一核心之上更快构建、上线和扩展财富业务": "從賬戶和金融產品，到交易、運營與 AI，FinOne 幫助機構在統一核心之上更快構建、上線和擴展財富業務",
  "从资产上线、Tokenization、持份管理到机构分销，认识 RWA 体系的关键环节。": "從資產上線、Tokenization、持份管理到機構分銷，認識 RWA 體系的關鍵環節。",
  "从资产上链到分销，": "從資產上鏈到分銷，",
