  "星企通可提供企业账户下的资产、持仓、交易及相关资金信息，具体展示范围根据账户和产品类型确定。": "星企通可提供企業賬戶下的資產、持倉、交易及相關資金信息，具體展示範圍根據賬戶和產品類型確定。",
  "星企通和支付平台里的企业财富 Web 有什么区别？": "星企通和支付平台里的企業財富 Web 有什麼區別？",
  "星企通围绕企业现金管理需求，为企业提供多样化的投资路径，通过货币基金、固定票息票据、债券基金等方式，在兼顾流动性与风险水平的同时，帮助企业提升闲置资金的使用效率。": "星企通圍繞企業現金管理需求，為企業提供多樣化的投資路徑，通過貨幣基金、固定票息票據、債券基金等方式，在兼顧流動性與風險水平的同時，幫助企業提升閒置資金的使用效率。",
  "星企通并非零售 App，而是围绕企业自身资金管理任务构建。": "星企通並非零售 App，而是圍繞企業自身資金管理任務構建。",
  "星企通应用": "星企通應用",
  "星企通是企业客户可直接注册和使用的公共平台；支付平台中的企业财富 Web 属于白标与嵌入式财富方案，由相应平台面向其客户提供服务。": "星企通是企業客戶可直接註冊和使用的公共平台；支付平台中的企業財富 Web 屬於白標與嵌入式財富方案，由相應平台面向其客戶提供服務。",
