  "星路科技": "星路科技",
  "星路科技 Finloop 是复星财富控股旗下的企业端机构财富科技平台。公司连接传统财富产品、机构交易、RWA 与 AI 能力，为多类金融机构及企业客户提供数字化财富管理、投资交易及智能化金融科技解决方案。": "星路科技 Finloop 是復星財富控股旗下的企業端機構財富科技平台。公司連接傳統財富產品、機構交易、RWA 與 AI 能力，為多類金融機構及企業客戶提供數字化財富管理、投資交易及智能化金融科技解決方案。",
  "星路自研金融交易与账户基础设施": "星路自研金融交易與賬戶基礎設施",
  "星路虚拟资产或稳定币产品 → 产品配置 → 投资者准入 → 交易或兑换 → 持仓与运营。": "星路虛擬資產或穩定幣產品 → 產品配置 → 投資者准入 → 交易或兌換 → 持倉與運營。",
  "星路通": "星路通",
  "星路通 · 金融专业 AI 工作台": "星路通 · 金融專業 AI 工作台",
  "星路通减少重复的信息查找、整理和初步分析工作，让专业人员把更多时间投入评估、沟通与决策。": "星路通減少重復的信息查找、整理和初步分析工作，讓專業人員把更多時間投入評估、溝通與決策。",
  "星路通应用": "星路通應用",
  "星路通提供金融 AI 工具广场，让机构可以围绕实际任务选择和扩展专业能力，并将这些能力统一带入日常工作流。": "星路通提供金融 AI 工具廣場，讓機構可以圍繞實際任務選擇和擴展專業能力，並將這些能力統一帶入日常工作流。",
  "星路通辅助读取和组织产品资料，提取关键事实、提示信息缺口，并形成可供专业人员审核的 KYP 与尽调工作成果。": "星路通輔助讀取和組織產品資料，提取關鍵事實、提示信息缺口，並形成可供專業人員審核的 KYP 與盡調工作成果。",
  "星路金融为香港证监会持牌法团。Finloop 依托复星财富控股旗下持牌金融机构体系，为机构财富、投资交易及相关金融服务提供合规基础设施支持。": "星路金融為香港證監會持牌法團。Finloop 依託復星財富控股旗下持牌金融機構體系，為機構財富、投資交易及相關金融服務提供合規基礎設施支持。",
