  "根据业务地区、主体与目标场景，组合适合的产品与运营能力。": "根據業務地區、主體與目標場景，組合適合的產品與運營能力。",
  "根据业务模式与规模灵活组合": "根據業務模式與規模靈活組合",
  "根据业务灵活接入": "根據業務靈活接入",
  "根据业务需求可提供现金管理、基金、债券、结构性产品等多种财富产品能力。其他资产类别的可用范围根据机构资质、账户及产品准入确定。": "根據業務需求可提供現金管理、基金、債券、結構性產品等多種財富產品能力。其他資產類別的可用範圍根據機構資質、賬戶及產品准入確定。",
  "根据产品扩展、用户反馈和业务数据持续优化。": "根據產品擴展、用戶反饋和業務數據持續優化。",
  "根据任务灵活调用": "根據任務靈活調用",
  "根据企业实际需求与准入条件，连接现金管理、基金、债券、结构性产品及其他适用资产。": "根據企業實際需求與准入條件，連接現金管理、基金、債券、結構性產品及其他適用資產。",
  "根据企业投资复杂度灵活组合": "根據企業投資複雜度靈活組合",
  "根据企业投资资格、风险偏好及资金期限，连接不同类型的传统及创新投资产品。": "根據企業投資資格、風險偏好及資金期限，連接不同類型的傳統及創新投資產品。",
  "根据企业账户及星企通当前支持范围提供相应币种能力，具体范围需结合实际业务确认。": "根據企業賬戶及星企通當前支持範圍提供相應幣種能力，具體範圍需結合實際業務確認。",
  "根据企业资格、投资者属性、产品准入及实际业务范围，可提供现金管理、基金、债券、结构性产品等适用理财产品。": "根據企業資格、投資者屬性、產品准入及實際業務範圍，可提供現金管理、基金、債券、結構性產品等適用理財產品。",
  "根据企业资金期限和流动性需求，为短期闲置资金提供灵活的现金管理及投资选择。": "根據企業資金期限和流動性需求，為短期閒置資金提供靈活的現金管理及投資選擇。",
  "根据企业资金规模、流动性需求和投资目标，配置适合的理财产品与投资方式，更清晰地管理资金、投资和未来现金安排。": "根據企業資金規模、流動性需求和投資目標，配置適合的理財產品與投資方式，更清晰地管理資金、投資和未來現金安排。",
  "根据你是现实资产方、数字资产产品需求方或产品提供方，组合相应业务能力。": "根據你是現實資產方、數字資產產品需求方或產品提供方，組合相應業務能力。",
  "根据使用反馈、准确性与模型变化持续优化。": "根據使用反饋、準確性與模型變化持續優化。",
  "根据具体任务选择适合的模型。": "根據具體任務選擇適合的模型。",
  "根据合作模式持续提供产品、系统、运营支持与优化。": "根據合作模式持續提供產品、系統、運營支持與優化。",
  "根据实际业务范围接入虚拟资产、稳定币相关产品，以及买卖、兑换、转入转出和资产管理能力。": "根據實際業務範圍接入虛擬資產、穩定幣相關產品，以及買賣、兌換、轉入轉出和資產管理能力。",
  "根据实际业务连接身份识别、反洗钱、投资者资格、钱包验证、地址风险识别和交易监控。": "根據實際業務連接身份識別、反洗錢、投資者資格、錢包驗證、地址風險識別和交易監控。",
  "根据平台基础选择接入方式": "根據平台基礎選擇接入方式",
