  "根据期限、币种和风险收益特征提供更多配置选择。": "根據期限、幣種和風險收益特徵提供更多配置選擇。",
  "根据机构业务与客户需求，灵活组合财富产品、股票投资及相关服务能力，形成适合自身业务的品牌化投资终端。": "根據機構業務與客戶需求，靈活組合財富產品、股票投資及相關服務能力，形成適合自身業務的品牌化投資終端。",
  "根据机构业务选择财富产品和功能模块。": "根據機構業務選擇財富產品和功能模塊。",
