  "根据机构的数据、安全、治理与基础设施要求，选择企业级 SaaS 或独立私有化部署。": "根據機構的數據、安全、治理與基礎設施要求，選擇企業級 SaaS 或獨立私有化部署。",
  "根据机构要求，选择适合自己的部署方式": "根據機構要求，選擇適合自己的部署方式",
