  "连接现金管理、公募基金、私募基金、债券、结构性产品、保险、虚拟资产与 RWA 等产品类别，为不同客户与资产配置场景提供多元选择。": "連接現金管理、公募基金、私募基金、債券、結構性產品、保險、虛擬資產與 RWA 等產品類別，為不同客戶與資產配置場景提供多元選擇。",
  "连接现金管理、基金、债券、结构性产品、保险、虚拟资产及 RWA 等产品方向。": "連接現金管理、基金、債券、結構性產品、保險、虛擬資產及 RWA 等產品方向。",
  "连接现金管理、基金、债券、结构性产品及其他适用财富产品，并结合币种、期限、流动性、风险和申赎规则配置产品范围。": "連接現金管理、基金、債券、結構性產品及其他適用財富產品，並結合幣種、期限、流動性、風險和申贖規則配置產品範圍。",
  "连接现金管理、基金、结构性产品、债券、保险及 RWA 等产品供给。": "連接現金管理、基金、結構性產品、債券、保險及 RWA 等產品供給。",
  "连接真实资产与链上业务，为资产代币化提供技术支撑，帮助机构拓展数字资产业务。": "連接真實資產與鏈上業務，為資產代幣化提供技術支撐，幫助機構拓展數字資產業務。",
  "连接终端、核心与企业财富场景": "連接終端、核心與企業財富場景",
  "连接虚拟资产 ETF 等产品，扩展传统财富之外的配置选择。": "連接虛擬資產 ETF 等產品，擴展傳統財富之外的配置選擇。",
  "连接虚拟资产 ETF 等合规投资产品，为适用机构提供传统金融之外的数字资产配置选择。KYT、钱包及出入金属于数字资产基础设施。": "連接虛擬資產 ETF 等合規投資產品，為適用機構提供傳統金融之外的數字資產配置選擇。KYT、錢包及出入金屬於數字資產基礎設施。",
  "连接虚拟资产 ETF 等投资产品；KYT、钱包及出入金属于数字资产基础设施，不应混同为投资产品。": "連接虛擬資產 ETF 等投資產品；KYT、錢包及出入金屬於數字資產基礎設施，不應混同為投資產品。",
  "连接虚拟资产、稳定币、钱包、交易与资金流转能力，帮助机构按实际业务范围扩展产品供给。": "連接虛擬資產、穩定幣、錢包、交易與資金流轉能力，幫助機構按實際業務範圍擴展產品供給。",
  "连接虚拟资产产品、机构账户与交易流程，支持适用机构拓展数字资产业务。": "連接虛擬資產產品、機構賬戶與交易流程，支持適用機構拓展數字資產業務。",
