  "连接金融产品资料、客户需求、市场信息与风险数据，辅助专业人员完成产品尽调、比较分析、配置判断和风险识别。": "連接金融產品資料、客戶需求、市場信息與風險數據，輔助專業人員完成產品盡調、比較分析、配置判斷和風險識別。",
  "连接金融机构、数字资产与企业业务场景，以专业技术和持续服务推动财富科技融入真实业务流程。": "連接金融機構、數字資產與企業業務場景，以專業技術和持續服務推動財富科技融入真實業務流程。",
