  "适应不同数字渠道的财富体验": "適應不同數字渠道的財富體驗",
  "适用于需要在既有品牌和客户关系中增加财富服务的合作机构，并根据实际项目确定前端、账户、交易与运营安排。": "適用於需要在既有品牌和客戶關係中增加財富服務的合作機構，並根據實際項目確定前端、賬戶、交易與運營安排。",
  "适用于需要私有化、数据隔离、权限控制与审计的业务。": "適用於需要私有化、數據隔離、權限控制與審計的業務。",
  "适用客群：零售客户 / 专业投资者（PI）": "適用客群：零售客戶 / 專業投資者（PI）",
  "适用机构": "適用機構",
  "适用的现金管理、基金及其他财富产品与持牌金融服务": "適用的現金管理、基金及其他財富產品與持牌金融服務",
  "适配不同云基础设施": "適配不同雲基礎設施",
